import { VALIDATION_MESSAGES } from './constants';

// Form validation helpers
export const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

export const validatePassword = (password) => {
  return password && password.length >= 8;
};

export const validatePhone = (phone) => {
  const phoneRegex = /^[+]?[(]?[\d\s\-\(\)]{10,}$/;
  return phoneRegex.test(phone);
};

export const validateRequired = (value) => {
  return value && value.toString().trim() !== '';
};

// Form validation for specific forms
export const validateLoginForm = (formData) => {
  const errors = {};
  
  if (!validateRequired(formData.username)) {
    errors.username = VALIDATION_MESSAGES.REQUIRED;
  }
  
  if (!validateRequired(formData.password)) {
    errors.password = VALIDATION_MESSAGES.REQUIRED;
  }
  
  return errors;
};

export const validateRegisterForm = (formData) => {
  const errors = {};
  
  if (!validateRequired(formData.username)) {
    errors.username = VALIDATION_MESSAGES.REQUIRED;
  }
  
  if (!validateRequired(formData.email)) {
    errors.email = VALIDATION_MESSAGES.REQUIRED;
  } else if (!validateEmail(formData.email)) {
    errors.email = VALIDATION_MESSAGES.EMAIL_INVALID;
  }
  
  if (!validateRequired(formData.password)) {
    errors.password = VALIDATION_MESSAGES.REQUIRED;
  } else if (!validatePassword(formData.password)) {
    errors.password = VALIDATION_MESSAGES.PASSWORD_TOO_SHORT;
  }
  
  if (!validateRequired(formData.confirmPassword)) {
    errors.confirmPassword = VALIDATION_MESSAGES.REQUIRED;
  } else if (formData.password !== formData.confirmPassword) {
    errors.confirmPassword = VALIDATION_MESSAGES.PASSWORDS_DONT_MATCH;
  }
  
  return errors;
};

export const validateVendorProfileForm = (formData) => {
  const errors = {};
  
  if (!validateRequired(formData.name)) {
    errors.name = VALIDATION_MESSAGES.REQUIRED;
  }
  
  if (!validateRequired(formData.cuisineSpecialties)) {
    errors.cuisineSpecialties = VALIDATION_MESSAGES.REQUIRED;
  }
  
  if (!validateRequired(formData.operatingRegion)) {
    errors.operatingRegion = VALIDATION_MESSAGES.REQUIRED;
  }
  
  if (!validateRequired(formData.phoneNumber)) {
    errors.phoneNumber = VALIDATION_MESSAGES.REQUIRED;
  } else if (!validatePhone(formData.phoneNumber)) {
    errors.phoneNumber = VALIDATION_MESSAGES.PHONE_INVALID;
  }
  
  if (!validateRequired(formData.businessAddress)) {
    errors.businessAddress = VALIDATION_MESSAGES.REQUIRED;
  }
  
  return errors;
};

// Date formatting helpers
export const formatDate = (dateString) => {
  if (!dateString) return 'N/A';
  const date = new Date(dateString);
  return date.toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric'
  });
};

export const formatDateTime = (dateString) => {
  if (!dateString) return 'N/A';
  const date = new Date(dateString);
  return date.toLocaleString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
};

// Status helpers
export const getStatusColor = (status) => {
  const statusColors = {
    DRAFT: 'gray',
    SUBMITTED: 'blue',
    UNDER_REVIEW: 'yellow',
    APPROVED: 'green',
    REJECTED: 'red',
    INSPECTION_SCHEDULED: 'orange',
    INSPECTION_COMPLETED: 'purple',
    LICENSED: 'green'
  };
  
  return statusColors[status] || 'gray';
};

export const getStatusText = (status) => {
  const statusTexts = {
    DRAFT: 'Draft',
    SUBMITTED: 'Submitted',
    UNDER_REVIEW: 'Under Review',
    APPROVED: 'Approved',
    REJECTED: 'Rejected',
    INSPECTION_SCHEDULED: 'Inspection Scheduled',
    INSPECTION_COMPLETED: 'Inspection Completed',
    LICENSED: 'Licensed'
  };
  
  return statusTexts[status] || status;
};

// Error handling helpers
export const getErrorMessage = (error) => {
  if (error.response) {
    // Server responded with error status
    if (error.response.data && error.response.data.error) {
      return error.response.data.error;
    }
    if (error.response.data && error.response.data.message) {
      return error.response.data.message;
    }
    return `Error: ${error.response.status}`;
  } else if (error.request) {
    // Request was made but no response received
    return 'Network error. Please check your connection.';
  } else {
    // Something else happened
    return error.message || 'An unexpected error occurred';
  }
};

// Local storage helpers
export const saveToLocalStorage = (key, value) => {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch (error) {
    console.error('Error saving to localStorage:', error);
  }
};

export const getFromLocalStorage = (key, defaultValue = null) => {
  try {
    const item = localStorage.getItem(key);
    return item ? JSON.parse(item) : defaultValue;
  } catch (error) {
    console.error('Error reading from localStorage:', error);
    return defaultValue;
  }
};

export const removeFromLocalStorage = (key) => {
  try {
    localStorage.removeItem(key);
  } catch (error) {
    console.error('Error removing from localStorage:', error);
  }
};

// Array helpers
export const isEmpty = (arr) => {
  return !arr || arr.length === 0;
};

export const isNotEmpty = (arr) => {
  return arr && arr.length > 0;
};

// Object helpers
export const hasProperty = (obj, prop) => {
  return obj && obj.hasOwnProperty(prop);
};

export const deepClone = (obj) => {
  return JSON.parse(JSON.stringify(obj));
};
